167	function activeGroupTitleOf(groups: NavGroup[], activeHref: string | null): string | null {
168	  if (!activeHref) return groups[0]?.title ?? null;
169	  return groups.find((g) => g.items.some((i) => i.href === activeHref))?.title ?? groups[0]?.title ?? null;
