50	export function getPeriodRange(
51	  period: Period,
52	  customFrom?: string,
53	  customTo?: string,
54	): DateRange {
55	  const today = todayStr();
56	  if (period === "today") {
57	    return { fromIso: wibStartOfDay(today), toIsoExclusive: null };
58	  }
59	  if (period === "week") {
60	    return { fromIso: wibStartOfDay(addDaysStr(today, -6)), toIsoExclusive: null };
61	  }
62	  if (period === "month") {
63	    return { fromIso: wibStartOfDay(`${today.slice(0, 7)}-01`), toIsoExclusive: null };
64	  }
65	  if (period === "custom") {
66	    const isDate = (s: string | undefined): s is string => !!s && /^\d{4}-\d{2}-\d{2}$/.test(s);
67	    return {
68	      fromIso: isDate(customFrom) ? wibStartOfDay(customFrom) : null,
69	      toIsoExclusive: isDate(customTo) ? wibStartOfDay(addDaysStr(customTo, 1)) : null,
70	    };
71	  }
72	  return { fromIso: null, toIsoExclusive: null };
73	}
